('pho-bo-ha-noi', 'Phở bò Hà Nội', 'Hanoi beef phở', '{}'::text[], 'savory', 'noodle-soup', 'pho', array['rice noodles','beef','beef bone broth','star anise','cinnamon','spring onion']::text[], array['umami','light','fragrant']::text[], 0, array['contains-beef']::text[], array['breakfast','lunch','late-night']::text[], 'Bánh phở trong nước dùng xương bò ninh lâu, thơm gừng nướng, hoa hồi, quế — phong cách thanh tao của miền Bắc.', 'Flat rice noodles in a clear, slow-simmered beef broth scented with charred ginger, star anise and cinnamon — the restrained northern style.', 1, 'seed', 'seed-unverified', null, null, null, now()),
('pho-ga-ha-noi', 'Phở gà Hà Nội', 'Hanoi chicken phở', '{}'::text[], 'savory', 'noodle-soup', 'pho', array['rice noodles','chicken','chicken broth','lime leaves','spring onion']::text[], array['light','fragrant']::text[], 0, array['contains-poultry']::text[], array['breakfast','lunch']::text[], 'Phở với thịt gà luộc, nước dùng xương gà và lá chanh thái chỉ.', 'A lighter phở with poached chicken, chicken-bone broth and finely shredded lime leaves.', 2, 'seed', 'seed-unverified', null, null, null, now()),
('pho-bo-nam-dinh', 'Phở bò Nam Định', 'Nam Định beef phở', '{}'::text[], 'savory', 'noodle-soup', 'pho', array['rice noodles','beef','beef broth','fish sauce']::text[], array['umami','rich']::text[], 0, array['contains-beef']::text[], array['breakfast','lunch']::text[], 'Phở Nam Định — một trong những cái nôi của phở, nước dùng đậm vị nước mắm.', 'The Nam Định tradition often credited as a cradle of phở, with a deeper, fish-sauce-seasoned broth.', 2, 'seed', 'seed-unverified', null, null, null, now()),
('pho-cuon', 'Phở cuốn', 'Phở rolls', '{}'::text[], 'savory', 'rolls', 'pho', array['uncut phở sheets','stir-fried beef','herbs','dipping sauce']::text[], array['fresh','herbal']::text[], 0, array['contains-beef']::text[], array['lunch','afternoon','dinner']::text[], 'Bánh phở lá cuốn thịt bò xào và rau thơm, đặc sản phố Ngũ Xã.', 'Wide sheets of fresh phở noodle rolled around stir-fried beef and herbs, a Ngũ Xã specialty.', 3, 'seed', 'seed-unverified', null, null, null, now()),
('pho-chua-lang-son', 'Phở chua Lạng Sơn', 'Lạng Sơn sour phở', '{}'::text[], 'savory', 'noodles', 'pho', array['rice noodles','roast pork','liver','peanuts','sour sauce','herbs']::text[], array['sour','sweet','crunchy']::text[], 1, array['contains-pork','contains-offal','contains-peanut']::text[], array['lunch']::text[], 'Phở trộn nguội với nước sốt chua ngọt, thịt quay, lòng và lạc rang.', 'A cold, dry phở dressed in a tangy sweet-sour sauce with roast pork, offal and peanuts.', 3, 'seed', 'seed-unverified', null, null, null, now()),
('pho-kho-gia-lai', 'Phở khô Gia Lai', 'Gia Lai dry phở (two-bowl phở)', '{}'::text[], 'savory', 'noodles', 'pho', array['thin rice noodles','minced pork','beef','broth served separately']::text[], array['umami','chewy']::text[], 0, array['contains-pork','contains-beef']::text[], array['breakfast','lunch']::text[], 'Sợi phở nhỏ dai trộn thịt băm, ăn kèm một bát nước dùng riêng — “phở hai tô”.', 'Thin, chewy noodles tossed with minced pork and served with a separate bowl of broth.', 2, 'seed', 'seed-unverified', null, null, null, now()),
('pho-sai-gon', 'Phở Sài Gòn', 'Saigon-style phở', '{}'::text[], 'savory', 'noodle-soup', 'pho', array['rice noodles','beef','sweeter broth','bean sprouts','Thai basil','hoisin']::text[], array['sweet','herbal','fragrant']::text[], 0, array['contains-beef']::text[], array['breakfast','lunch','late-night']::text[], 'Phở kiểu miền Nam: nước dùng ngọt hơn, ăn kèm giá, húng quế và tương đen.', 'The southern interpretation: a slightly sweeter broth served with a plate of fresh herbs, sprouts and sauces.', 3, 'seed', 'seed-unverified', null, null, null, now()),
('bun-cha-ha-noi', 'Bún chả Hà Nội', 'Hanoi grilled pork with noodles', '{}'::text[], 'savory', 'noodles', null, array['rice vermicelli','grilled pork patties','pork belly','dipping broth','herbs','green papaya']::text[], array['smoky','sweet','sour']::text[], 0, array['contains-pork']::text[], array['lunch']::text[], 'Chả viên và chả miếng nướng than hoa ngâm trong nước chấm chua ngọt, ăn với bún và rau sống.', 'Charcoal-grilled pork patties and belly served in a warm sweet-sour fish-sauce dip with vermicelli and herbs.', 1, 'seed', 'seed-unverified', null, null, null, now()),
('bun-thang', 'Bún thang', 'Bún thang', '{}'::text[], 'savory', 'noodle-soup', null, array['rice vermicelli','shredded chicken','egg ribbons','pork roll','dried shrimp broth']::text[], array['light','umami']::text[], 0, array['contains-poultry','contains-egg','contains-pork']::text[], array['breakfast','lunch']::text[], 'Món bún cầu kỳ của Hà Nội với gà xé, trứng tráng thái chỉ, giò lụa và nước dùng thanh.', 'An intricate Hanoi noodle soup of shredded chicken, egg ribbons and pork roll in a delicate broth.', 2, 'seed', 'seed-unverified', null, null, null, now()),
