('lau-mam', 'Lẩu mắm', 'Fermented fish hotpot', '{}'::text[], 'savory', 'hotpot', null, array['fermented fish broth','pork','shrimp','fish','eggplant','many river greens']::text[], array['fermented','umami','rich']::text[], 1, array['contains-fish','contains-pork','contains-seafood']::text[], array['dinner']::text[], 'Lẩu nấu từ mắm cá, ăn cùng hải sản và rất nhiều rau đồng.', 'A pungent hotpot of fermented fish broth with seafood and baskets of Mekong vegetables.', 2, 'seed', 'seed-unverified', null, null, null, now()),
